import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(startOfDay(new Date()));

  const presets = [
    { label: 'Сегодня', date: startOfDay(new Date()) },
    { label: 'Вчера', date: startOfDay(addDays(new Date(), -1)) },
    { label: 'Неделя назад', date: startOfDay(addDays(new Date(), -7)) },
  ];

  const applyDate = (date: Date) => {
    setValue(date);
    onChange?.(date);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-xs)' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.label}
            active={value?.getTime() === preset.date.getTime()}
            onClick={() => applyDate(preset.date)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar
        locale="ru-RU"
        value={value}
        onValueChange={(date) => {
          setValue(date);
          if (date) {
            onChange?.(date);
          }
        }}
      />
    </div>
  );
}

